public static void check(Solution solution) {
    assert Arrays.equals(solution.vowelStrings(new int[]{"aeiou","bcd","cde","ua"}, new int[]{{0,0},{1,2},{0,3}}), new int[]{1, 0, 2});
    assert Arrays.equals(solution.vowelStrings(new int[]{"aeiou","bcd","cde","dea"}, new int[]{{0,3},{1,2},{2,2}}), new int[]{1, 0, 0});
    assert Arrays.equals(solution.vowelStrings(new int[]{"aeiou","bcd","cde","aeiou"}, new int[]{{0,3},{1,2},{3,3}}), new int[]{2, 0, 1});
